from pathlib import Path
from html.parser import HTMLParser
import hashlib
import json
import re

class VisibleText(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.hidden = 0
        self.chunks = []

    def handle_starttag(self, tag, attrs):
        if tag in {'script', 'style'}:
            self.hidden += 1

    def handle_endtag(self, tag):
        if tag in {'script', 'style'} and self.hidden:
            self.hidden -= 1

    def handle_data(self, data):
        if not self.hidden:
            text = ' '.join(data.split())
            if text:
                self.chunks.append(text)

base = Path('products/services/sqlite-international-payment')
source = base / 'raw/stripe-payment-links.html'
raw = source.read_bytes()
actual_hash = hashlib.sha256(raw).hexdigest()
assert actual_hash == '526b0fbecd1cce86f0c470078bb6b979b1fddedac938aad7e45c199d84f190b0', 'Capture differs from the fetch receipt'
parser = VisibleText()
parser.feed(raw.decode('utf-8'))
patterns = {'link_controls': r'limit|deactivat|after payment', 'currency_and_geography': r'currenc|international|countr', 'payment_and_payout': r'payment method|payout|fee'}
excerpts = {}
for label, pattern in patterns.items():
    matches = [index for index, text in enumerate(parser.chunks) if re.search(pattern, text, re.I)]
    excerpts[label] = {'match_count': len(matches), 'snippets': list(dict.fromkeys(' '.join(parser.chunks[max(0, index - 1):index + 2])[:480] for index in matches))[:12]}
report = {'source': 'https://docs.stripe.com/payment-links', 'fetch_task': 'TASK-179559216101', 'sha256': actual_hash, 'excerpts': excerpts, 'scope': 'Text pointers from one saved documentation page. Review surrounding original text before drawing conclusions about Canadian seller eligibility, current pricing, payment limits or payout.'}
output = base / 'director-payment-link-excerpts.json'
output.write_text(json.dumps(report, ensure_ascii=False, indent=2) + '\n', encoding='utf-8')
print(output.read_text(encoding='utf-8'))
